param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
function Polygon([double[]]$rows,[double[]]$columns){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns);$x}
function Concat($objects){[HalconDotNet.HObject]$all=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all);foreach($one in $objects){[HalconDotNet.HObject]$combined=$null;try{[HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined);$all.Dispose();$all=$combined;$combined=$null}finally{if($null-ne$combined){$combined.Dispose()}}};Write-Output -NoEnumerate $all}

$temp=Join-Path ([IO.Path]::GetTempPath()) ('halcon-vm-s50-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$f=$mainType.GetField($name,$all);if($null-eq$f){throw "Missing field $name"};$v=$f.GetValue($window);Write-Output -NoEnumerate $v}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}

# A: quiet-by-default information density and the layer task no longer occupies/overlays the image viewport.
Assert((Field 'BottomTabs').Visibility.ToString()-eq'Collapsed') 'Bottom result/log/history panel is not collapsed by default'
Assert((Field 'BottomPanelRow').Height.Value-eq0) 'Bottom panel still consumes default height'
Assert((Field 'FlowDebugMonitorBorder').Visibility.ToString()-eq'Collapsed') 'Debug monitor remains permanently exposed'
Assert((Field 'FlowDebugMonitorColumn').Width.Value-eq0) 'Debug monitor still consumes graph width'
Assert([object]::ReferenceEquals((Field 'RoiLayerPanel').Parent,(Field 'RightLayerTaskHost'))) 'Layer workspace was not moved to the right task surface'
Assert((Field 'RoiLayerPanelColumn').Width.Value-eq0) 'Legacy image-side layer column still consumes image width'
foreach($name in @('DeveloperMoreToggleButton','FlowMoreToggleButton','RoiToolsToggleButton','ImageMoreToggleButton')){Assert((Field $name).IsChecked-ne$true) "$name should be collapsed by default"}
$flow=Field 'flowTools';$a=Tool XldPointClosureFilter 'Compact A';$b=Tool XldContourFilter 'Compact B';$b.SetInputBinding('XLD',$a.ToolId,'XLD');$flow.Add($a);$flow.Add($b);$mainType.GetMethod('RefreshFlowPortVisualization',$private).Invoke($window,@())|Out-Null;Assert($a.GraphHeight-eq68-and$b.GraphHeight-eq68) 'Unselected graph nodes are not compact summary cards';(Field 'FlowToolList').SelectedItem=$b;$mainType.GetMethod('FlowToolList_SelectionChanged',$private).Invoke($window,[object[]]@((Field 'FlowToolList'),$null))|Out-Null;Assert($b.GraphHeight-eq68-and$a.GraphHeight-eq68) 'Selecting a node should keep the compact task summary';$b.IsFlowDetailExpanded=$true;(Field 'FlowToolList').SelectedItems.Clear();$mainType.GetMethod('RefreshFlowPortVisualization',$private).Invoke($window,@())|Out-Null;Assert($b.GraphHeight-gt68) 'Manual node detail expansion failed'

# B: real smallest_circle_xld + diameter_xld, open/closed/self-intersect/degenerate semantics and managed outputs.
$kind=[Enum]::Parse($kindType,'XldEnclosingCircleDiameterMeasurement');$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($kind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($kind));Assert(($inputs|Where-Object PortName -eq XLD).Count-eq1-and($outputs|Where-Object PortName -eq Diameter).DataType-eq'Number'-and($outputs|Where-Object PortName -eq XLD).DataType-eq'XLD') 'Typed enclosing geometry ports missing'
$angles=0..36|ForEach-Object{$_*[Math]::PI/18};$circle=Polygon ([double[]]($angles|ForEach-Object{50+30*[Math]::Sin($_)})) ([double[]]($angles|ForEach-Object{60+30*[Math]::Cos($_)}));$open=Polygon ([double[]]@(0,0,20,20)) ([double[]]@(0,30,30,0));$bowtie=Polygon ([double[]]@(0,20,0,20,0)) ([double[]]@(0,20,20,0,0));$degenerate=Polygon ([double[]]@(10,10,10)) ([double[]]@(10,10,10));$input=Concat @($circle,$open,$bowtie,$degenerate);foreach($x in @($circle,$open,$bowtie,$degenerate)){$x.Dispose()}
$measure=Tool XldEnclosingCircleDiameterMeasurement 'S50 Enclosing Geometry';$run=$mainType.GetMethod('RunXldEnclosingCircleDiameterMeasurementTool',$private);function RunMeasure($x){try{$run.Invoke($window,[object[]]@($measure,$x.PSObject.BaseObject))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
try{$measure.Parameters.XldEnclosingContourMode='All';$measure.Parameters.XldEnclosingMinimumPointCount=2;$measure.Parameters.XldEnclosingClosureTolerance=0;$measure.Parameters.XldEnclosingDiameterMinimum=0;$measure.Parameters.XldEnclosingDiameterMaximum=1000;$result=RunMeasure $input;Assert($result.ResultCode-eq'OK'-and[int](Out $measure MeasuredCount)-eq3-and[int](Out $measure ContourCount)-eq3) 'All-point-set measurement failed';Assert([int](Out $measure OpenCount)-eq1-and[int](Out $measure ClosedCount)-eq3-and[int](Out $measure SelfIntersectingCount)-eq1-and[int](Out $measure DegenerateCount)-eq1) 'Open/closed/self-intersect/degenerate counters failed';Assert([Math]::Abs([double](Out $measure Radius)-30)-lt.05-and[Math]::Abs([double](Out $measure Diameter)-60)-lt.05) 'Primary smallest circle/diameter geometry is incorrect';[HalconDotNet.HObject]$copy=(Out $measure XLD).CreateXldCopy();try{[HalconDotNet.HTuple]$overlayCount=$null;[HalconDotNet.HOperatorSet]::CountObj($copy,[ref]$overlayCount);Assert($overlayCount.I-eq6) 'Circle + diameter overlay object count is incorrect'}finally{$copy.Dispose()};$old=Out $measure XLD;$measure.Parameters.XldEnclosingContourMode='ClosedOnly';RunMeasure $input|Out-Null;Assert([int](Out $measure ContourCount)-eq2-and$old.IsDisposed) 'Closed-only policy or old snapshot release failed';$measure.Parameters.XldEnclosingContourMode='All';$measure.Parameters.XldEnclosingDiameterMinimum=59.9;$measure.Parameters.XldEnclosingDiameterMaximum=60.1;RunMeasure $input|Out-Null;Assert([int](Out $measure ContourCount)-eq1-and(Out $measure OriginalIndices)-eq'[1]') 'Inclusive diameter range selection failed';[HalconDotNet.HTuple]$sourceCount=$null;[HalconDotNet.HOperatorSet]::CountObj($input,[ref]$sourceCount);Assert($sourceCount.I-eq4) 'Upstream XLD ownership changed'}finally{$input.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$measure.Parameters.XldEnclosingDiameterMinimum=0;$measure.Parameters.XldEnclosingDiameterMaximum=1000;$emptyResult=RunMeasure $empty;Assert($emptyResult.ResultCode-eq'NG'-and[int](Out $measure ContourCount)-eq0) 'Empty input semantics failed'}finally{$empty.Dispose()}
$measure.Parameters.XldEnclosingMinimumPointCount=1;Assert(-not[string]::IsNullOrWhiteSpace($measure.Parameters.Validate($kind))) 'Invalid minimum point count accepted';$measure.Parameters.XldEnclosingMinimumPointCount=2;$measure.Parameters.XldEnclosingDiameterMinimum=10;$measure.Parameters.XldEnclosingDiameterMaximum=5;Assert(-not[string]::IsNullOrWhiteSpace($measure.Parameters.Validate($kind))) 'Invalid diameter range accepted';$measure.Parameters.XldEnclosingDiameterMinimum=0;$measure.Parameters.XldEnclosingDiameterMaximum=1000
$producer=Tool XldPointClosureFilter 'S50 Geometry Source';$chain=Tool XldEnclosingCircleDiameterMeasurement 'S50 Geometry Measure';$judge=Tool NumericJudge 'S50 Diameter Judge';$chain.SetInputBinding('XLD',$producer.ToolId,'XLD');$judge.SetInputBinding('Value',$chain.ToolId,'Diameter');$judge.InputToolId=$chain.ToolId;$judge.InputPortName='Diameter';$judge.NumericLowerLimit=59;$judge.NumericUpperLimit=61;$flow.Add($producer);$flow.Add($chain);$flow.Add($judge);$source=Polygon ([double[]]($angles|ForEach-Object{100+30*[Math]::Sin($_)})) ([double[]]($angles|ForEach-Object{110+30*[Math]::Cos($_)}));try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($source.PSObject.BaseObject,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$source.Dispose()};$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$execute.Invoke($window,[object[]]@($chain,'S50 chain'))|Out-Null;$execute.Invoke($window,[object[]]@($judge,'S50 chain'))|Out-Null;Assert($chain.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Real XLD/Number downstream chain failed'
(Field 'FlowToolList').SelectedItem=$measure;$measure.Parameters.XldEnclosingContourMode='OpenOnly';$measure.Parameters.XldEnclosingMinimumPointCount=5;$measure.Parameters.XldEnclosingClosureTolerance=2;$measure.Parameters.XldEnclosingDiameterMinimum=12;$measure.Parameters.XldEnclosingDiameterMaximum=90;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($measure))|Out-Null;Assert((Field 'DockXldEnclosingCircleDiameterPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldEnclosingMinimumPointCountTextBox').Text-eq'5') 'Dock configuration synchronization failed';$flow.Add($measure);$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object{$_.ToolId-eq$measure.ToolId}|Select-Object -First 1;Assert($saved.Parameters.XldEnclosingContourMode-eq'OpenOnly'-and$saved.Parameters.XldEnclosingDiameterMinimum-eq12-and$saved.Parameters.XldEnclosingDiameterMaximum-eq90) 'Recipe persistence failed'
$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S50 quiet workspace and HALCON XLD enclosing-circle/diameter smoke tests passed; BSB not implemented by user directive.'
